      displayTasks();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });

  return api(`/api/projects/${projectId}/tasks`).then((saved) => {
    tasks = saved;
    displayTasks();
    submit.disabled = project.archived;
  });
}

